import{C as r,o as p,c,E as e,a2 as s,j as l,a5 as n,a6 as o}from"./chunks/framework.CkaEw-3u.js";const h={class:"reference-parameter-grid reference-parameter-grid-2"},y=JSON.parse('{"title":"スクリプティング設定 (Scripting Settings)","description":"Luaスクリプトの有効化とスクリプト本文の設定、実行制限の詳細","frontmatter":{"title":"スクリプティング設定 (Scripting Settings)","description":"Luaスクリプトの有効化とスクリプト本文の設定、実行制限の詳細","pageClass":"reference-page","head":[["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/reference/reference-scripting-settings.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"スクリプティング設定 (Scripting Settings) | Mug Typography Manual"}],["meta",{"property":"og:description","content":"Luaスクリプトの有効化とスクリプト本文の設定、実行制限の詳細"}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/reference/reference-scripting-settings.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Online Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"スクリプティング設定 (Scripting Settings) | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"Luaスクリプトの有効化とスクリプト本文の設定、実行制限の詳細"}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Online Manual"}]]},"headers":[],"relativePath":"reference/reference-scripting-settings.md","filePath":"reference/reference-scripting-settings.md"}'),g={name:"reference/reference-scripting-settings.md"},b=Object.assign(g,{setup(u){const i={standardPreset:{image:"/image/inspector_scripting_standard.webp",alt:"通常プリセットのScriptingページ",label:"通常プリセット · Scriptingページ",sourceWidth:615,sourceHeight:454,top:0,bottom:454},scriptingPreset:{image:"/image/inspector_scripting_preset.webp",alt:"Mug Typography ScriptingプリセットのGlobalページ",label:"Scriptingプリセット · Globalページ",sourceWidth:609,sourceHeight:457,top:0,bottom:457},scriptInputs:{image:"/image/inspector_scripting_inputs.webp",alt:"Script Inputsグループ",label:"Script Inputs",sourceWidth:607,sourceHeight:657,top:0,bottom:657}};return(m,t)=>{const d=r("ReferenceOverview"),a=r("InspectorCrop");return p(),c("div",null,[e(d,{eyebrow:"PARAMETER REFERENCE",title:"Scripting Settings",description:"Lua 5.4スクリプトによるプロシージャルなアニメーション制御を設定します。",items:[{icon:"▤",title:"Inspector",description:"プリセットごとの表示位置",href:"#インスペクタでの表示"},{icon:"⇥",title:"Control",description:"スクリプトから制御できるもの",href:"#スクリプトから制御できるもの"},{icon:"🎬",title:"Edit Page",description:"Generator使用時の注意",href:"#edit-pageでの使用上の注意"},{icon:"⚠️",title:"制限事項",description:"エラー時の挙動と実行制限",href:"#エラー時の挙動と実行制限"}]}),t[0]||(t[0]=s('<p>通常の2D / 3D / Liteプリセットでは、インスペクタの <strong>Page</strong> で <code>Scripting</code> を選択すると表示されるページです。専用の<code>Mug Typography Scripting</code>プリセットでは、同じ設定が<strong>Globalページ内</strong>に表示されます。機能の概要と作例は「<a href="/mug-typography-docs/features/feature-scripting.html">Luaスクリプトで動かす（Scripting）</a>」を参照してください。</p><div class="info custom-block"><p class="custom-block-title">Mug Typography Scriptingプリセット</p><p>Character SettingsとPart Settingsを省略し、最大512文字・1024パーツをLuaから制御する用途に特化したプリセットです。Global設定と3DのCamera設定は利用できますが、Character / Part選択モード、Copy / Paste、文字・パーツを対象とするRandomizeは表示されません。</p></div><h2 id="インスペクタでの表示" tabindex="-1">インスペクタでの表示 <a class="header-anchor" href="#インスペクタでの表示" aria-label="Permalink to &quot;インスペクタでの表示&quot;">​</a></h2><p>通常プリセットでは<strong>Pageを<code>Scripting</code>へ切り替えて</strong>設定します。専用のMug Typography Scriptingプリセットでは、同じScriptingグループが<strong>Globalページ内に常時表示</strong>されます。</p>',4)),l("div",h,[e(a,n(o(i.standardPreset)),null,16),e(a,n(o(i.scriptingPreset)),null,16)]),t[1]||(t[1]=s('<h2 id="パラメーター" tabindex="-1">パラメーター <a class="header-anchor" href="#パラメーター" aria-label="Permalink to &quot;パラメーター&quot;">​</a></h2><table tabindex="0"><thead><tr><th>パラメーター</th><th>説明</th><th>デフォルト</th></tr></thead><tbody><tr><td><strong>Script Enabled</strong></td><td>レンダリング時にScript TextのLuaスクリプトを実行します。通常は時間依存として評価します。<code>@time_independent</code>を宣言すると、条件が変わらないフレームで描画結果を再利用できます（<a href="#time-independent">詳細</a>）。</td><td>OFF</td></tr><tr><td><strong>Script Text</strong></td><td>実行するLua 5.4スクリプト本文（複数行）。<code>OnInitialize(ctx)</code> / <code>OnPreLayout(ctx)</code> / <code>OnLayout(ctx)</code> / <code>OnPath(ctx)</code> を定義します。</td><td><code>OnLayout</code> の雛形</td></tr><tr><td><strong>Copy Script</strong></td><td>Script Textの内容をOSのクリップボードへコピーします。MT Simや外部エディタへ戻すときに使用します。</td><td>—</td></tr><tr><td><strong>Paste Script</strong></td><td>OSのクリップボードにあるテキストでScript Textを置き換えます。ホストのUndoで元に戻せます。</td><td>—</td></tr><tr><td><strong>Script Status</strong></td><td>通常時はプラグイン本体が対応するAPIレベルを表示します。スクリプトの<code>@api_level</code>が対応レベルを超える場合は、必要なAPIレベルと本体の対応レベルを表示し、実行を停止します。</td><td><code>API Level 10</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">スクリプトの開発はVSCode拡張で</p><p>Script Text欄はスクリプトの「供給口」であり、エディタとしての支援機能はありません。開発・デバッグには配布ZIP同梱のVSCode拡張「Mug Typography Scripting Simulator」(MT Sim) を使い、MT SimのCopy ScriptとプラグインのPaste Scriptで完成したスクリプトを移す運用を推奨します。</p></div><h2 id="スクリプトから制御できるもの" tabindex="-1">スクリプトから制御できるもの <a class="header-anchor" href="#スクリプトから制御できるもの" aria-label="Permalink to &quot;スクリプトから制御できるもの&quot;">​</a></h2><table tabindex="0"><thead><tr><th>コールバック</th><th>書き込み先</th></tr></thead><tbody><tr><td><code>OnPreLayout</code></td><td><code>ctx.global</code>（テキスト・フォントサイズ・字送り・行間・整列・縦書き・位置・回転・スケール・塗り・グラデーション・ストローク・影など）、<code>ctx.camera</code>（3D / Scriptingプリセット）</td></tr><tr><td><code>OnLayout</code></td><td><code>ctx.chars[index]</code> / <code>ctx.parts[index]</code>（位置・回転・スケール・ピボット・個別色・個別ストローク・個別影・3D姿勢）、<code>ctx.bounding_box</code>、<code>ctx.output</code>（Write On）</td></tr><tr><td><code>OnPath</code></td><td><code>ctx.paths</code>から選択したパーツの輪郭パス</td></tr></tbody></table><p>読み取り専用の情報として <code>ctx.time</code>（秒）、<code>ctx.frame</code>、<code>ctx.timeline</code>（クリップ長・進捗）、<code>ctx.font</code>、<code>ctx.meta</code>（APIレベル・プリセット能力・上限値）、文字・パーツの <code>geometry</code>（実測ジオメトリ）が利用できます。完全な仕様は「<a href="/mug-typography-docs/scripting/api-reference.html">Luaスクリプティング APIリファレンス</a>」を参照してください。</p><h3 id="インスペクタから値を渡す-script-inputs" tabindex="-1">インスペクタから値を渡す（Script Inputs） <a class="header-anchor" href="#インスペクタから値を渡す-script-inputs" aria-label="Permalink to &quot;インスペクタから値を渡す（Script Inputs）&quot;">​</a></h3><p>スクリプト側で <code>@input</code> を宣言すると、<strong>Script Inputs</strong>グループに入力欄が現れ、スクリプトを書き換えずにインスペクタから値を調整できます。読み取りは <code>ctx.inputs</code> から行います。</p>',8)),e(a,n(o(i.scriptInputs)),null,16),t[2]||(t[2]=s(`<div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- @input number 1 &quot;Amplitude&quot; default=15.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- @input boolean 1 &quot;Enable Glow&quot; default=true</span></span></code></pre></div><table tabindex="0"><thead><tr><th>種類</th><th>数</th><th>インスペクタ表示</th><th>初期値</th></tr></thead><tbody><tr><td>数値</td><td>10個</td><td><code>Number 1</code> 〜 <code>Number 10</code></td><td><code>0.0</code></td></tr><tr><td>カラー</td><td>4個</td><td><code>Color 1</code> 〜 <code>Color 4</code></td><td>白（<code>#ffffff</code>）</td></tr><tr><td>テキスト</td><td>2個</td><td><code>Text 1</code> / <code>Text 2</code></td><td>空</td></tr><tr><td>真偽値（チェックボックス）</td><td>4個</td><td><code>Boolean 1</code> 〜 <code>Boolean 4</code></td><td>OFF</td></tr></tbody></table><p>数値・カラー・真偽値はキーフレームを設定できます。真偽値のスロットはv6.1aで追加されました。<strong>宣言した欄だけが表示され</strong>、<code>@input</code> が1つも無いスクリプトではグループ自体が隠れます。</p><p>グループ内の <strong>Reset Inputs</strong> を押すと、現在のスクリプトが宣言しているすべての入力が宣言された初期値へ戻ります。</p><p>スクリプトを差し替えたときは、新しく増えた欄と初期値が変わった欄にだけ初期値が入り、設定済みの値とキーフレームは保持されます。宣言の書式と制限は「<a href="/mug-typography-docs/scripting/api-reference.html">Luaスクリプティング APIリファレンス</a>」を参照してください。</p><h2 id="time-independent" tabindex="-1">時間非依存の宣言と描画結果の再利用 <a class="header-anchor" href="#time-independent" aria-label="Permalink to &quot;時間非依存の宣言と描画結果の再利用 {#time-independent}&quot;">​</a></h2><p><strong>インスペクタの値が同じなら、時刻が変わっても同じ結果になるスクリプト</strong>には、ヘッダーに <code>-- @time_independent</code> を追加できます。値は指定しません。たとえば、入力した角度で文字を段階的に回転させる静的な配置に使えます。</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- @MugTypography</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- @time_independent</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- @input number 1 &quot;Angle Step&quot; default=5.0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OnLayout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index, character </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mt.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">each_char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        character.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rotation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inputs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">numbers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    end</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>宣言はファイル先頭の連続する <code>--</code> コメント内に置き、空行・字下げされた行・本文・<code>--[[</code> ブロックコメントより前に記述してください。省略時は従来どおり時間依存として扱います。</p><p>宣言があり、他の時間依存エフェクトが動作していなければ、インスペクタ値・スクリプト本文・描画サイズなどが変わらずキャッシュが有効な間は、前回の文字描画結果を再利用します。再利用するフレームではLuaの実行と文字の再描画を省略します。入力映像への合成はそのフレームの映像を使います。このスクリプトはホストへの時間依存通知からも除外されます。</p><p><code>@input</code> を含むインスペクタ値がキーフレームで変われば再描画するため、インスペクタ側のアニメーションとは併用できます。スクリプトの変更、キャッシュの消失、Pulseなど別の時間依存エフェクトがある場合も再描画の対象です。</p><div class="warning custom-block"><p class="custom-block-title">時間で動くスクリプトには宣言しないでください</p><p>これは作者が結果の時間非依存性を保証する宣言で、自動判定ではありません。<code>ctx.time</code>・<code>ctx.frame</code>・<code>ctx.timeline</code>、呼び出し回数や外部状態などで結果が変わるスクリプトには設定しないでください。誤って設定すると、前の描画結果が使われてアニメーションが止まる場合があります。判断できない場合は省略してください。</p></div><p>MT Simは宣言を読み取りますが、プレビューではフレーム評価を継続します。再利用時の挙動はプラグイン本体でも確認してください。</p><h2 id="edit-pageでの使用上の注意" tabindex="-1">Edit Pageでの使用上の注意 <a class="header-anchor" href="#edit-pageでの使用上の注意" aria-label="Permalink to &quot;Edit Pageでの使用上の注意&quot;">​</a></h2><p><strong>Generatorプリセットでは、クリップの分割や0フレームより前への拡張に制限があります。</strong></p><p>これらの操作を行うと、DaVinci Resolveから正しい時間情報が渡されず、<code>ctx.time</code>を使うアニメーションが崩れる場合があります。</p><p>操作を避けるか、Adjustment Clip（調整クリップ）へFilters側のMug Typographyプリセットを適用してください。</p><h2 id="エラー時の挙動と実行制限" tabindex="-1">エラー時の挙動と実行制限 <a class="header-anchor" href="#エラー時の挙動と実行制限" aria-label="Permalink to &quot;エラー時の挙動と実行制限&quot;">​</a></h2><p>ホストでスクリプトのロード、初期化、またはコールバックが失敗すると、<strong>そのフレームは描画されません</strong>。失敗までに行われた変更のロールバックは保証されませんが、未完了の結果が描画に使われることはありません。次のフレームはホスト由来の値から再評価されます。</p><table tabindex="0"><thead><tr><th>失敗箇所</th><th>結果</th></tr></thead><tbody><tr><td>スクリプトロード</td><td>そのスクリプトを実行せず、フレームを描画しない</td></tr><tr><td><code>OnInitialize</code></td><td>フレーム評価を開始せず、描画しない</td></tr><tr><td><code>OnPreLayout</code></td><td>後続コールバックを実行せず、描画しない</td></tr><tr><td><code>OnLayout</code></td><td><code>OnPath</code>を実行せず、描画しない</td></tr><tr><td><code>OnPath</code></td><td>描画しない</td></tr></tbody></table><p>暴走防止のため、1コールバック呼び出しあたり <strong>5,000,000命令</strong>、メモリ <strong>128MiB</strong> の上限があります。メモリは必要な分だけ確保されます。上限を超えたコールバックはエラーとして扱われ、そのフレームは描画されません。</p><div class="warning custom-block"><p class="custom-block-title">制限事項</p><ul><li>スクリプトが書き込んだ値はそのフレームの描画にのみ使われ、インスペクタやキーフレームへは書き戻されません</li><li>モーフアニメーションの実行中（To Textによる変形中）はスクリプトのコールバックはスキップされます</li><li>外部 <code>.lua</code> ファイルの読み込みには対応していません</li></ul></div>`,22))])}}});export{y as __pageData,b as default};
